1	// shop: a small HTTP service on Postgres.
2	//   GET /order?customer=C&amount=A[&email=E]  -> insert an order (guest orders have no email)
3	//   GET /order/ID                             -> read one order
4	//   GET /customer/C                           -> a customer's last 10 orders (slow without an index)
5	// Which columns the app uses is set by environment variables:
6	//   AMOUNT_READ   column the amount is read from            (default: amount)
7	//   AMOUNT_WRITE  column(s) the amount is written to, comma (default: amount)
8	//   GUEST_EMAIL   what a guest order stores as email: null | empty   (default: null)
9	// Every query has a 2 s statement timeout.
10	const http = require("http");
11	const { Pool } = require("pg");
12	
13	const AMOUNT_READ = process.env.AMOUNT_READ || "amount";
14	const AMOUNT_WRITE = (process.env.AMOUNT_WRITE || "amount").split(",").map((s) => s.trim()).filter(Boolean);
15	const GUEST_EMAIL = process.env.GUEST_EMAIL === "empty" ? "" : null;
16	const ident = (s) => { if (!/^[a-z_][a-z0-9_]*$/.test(s)) throw new Error("bad column name " + s); return s; };
17	
18	const pool = new Pool({
19	  connectionString: process.env.DATABASE_URL,
20	  max: 8,
21	  connectionTimeoutMillis: 2000,
22	  options: "-c statement_timeout=2000",
23	});
24	
25	const insertSql = `INSERT INTO orders (customer_id, ${AMOUNT_WRITE.map(ident).join(", ")}, status, email)
26	                   VALUES ($1, ${AMOUNT_WRITE.map(() => "$2").join(", ")}, 'new', $3) RETURNING id`;
27	const readSql = `SELECT id, customer_id, ${ident(AMOUNT_READ)} AS amount, status, email FROM orders WHERE id = $1`;
28	const customerSql = `SELECT id, ${ident(AMOUNT_READ)} AS amount FROM orders WHERE customer_id = $1 ORDER BY id DESC LIMIT 10`;
29	
30	let stopping = false;
31	function send(res, code, body) {
32	  res.writeHead(code, { "content-type": "application/json", ...(stopping ? { connection: "close" } : {}) });
33	  res.end(JSON.stringify(body));
34	}
35	
36	const server = http.createServer(async (req, res) => {
37	  const url = new URL(req.url, "http://x");
38	  try {
39	    if (url.pathname === "/healthz") return send(res, stopping ? 503 : 200, { ok: !stopping });   // not ready once stopping
40	    if (url.pathname === "/order") {
41	      const email = url.searchParams.get("email") || GUEST_EMAIL;
42	      const r = await pool.query(insertSql, [Number(url.searchParams.get("customer")), url.searchParams.get("amount"), email]);
43	      return send(res, 200, { id: r.rows[0].id });
44	    }
45	    let m = url.pathname.match(/^\/order\/(\d+)$/);
46	    if (m) {
47	      const r = await pool.query(readSql, [m[1]]);
48	      return r.rows.length ? send(res, 200, r.rows[0]) : send(res, 404, { error: "not found" });
49	    }
50	    m = url.pathname.match(/^\/customer\/(\d+)$/);
51	    if (m) {
52	      const r = await pool.query(customerSql, [m[1]]);
53	      return send(res, 200, { orders: r.rows });
54	    }
55	    send(res, 404, { error: "no route" });
56	  } catch (e) {
57	    send(res, 500, { error: String(e.message || e).slice(0, 200) });
58	  }
59	});
60	server.listen(8080, () => console.log(`shop on 8080: read ${AMOUNT_READ}, write ${AMOUNT_WRITE}, guest email ${GUEST_EMAIL === null ? "NULL" : "''"}`));
61	
62	// Graceful shutdown. Node runs as PID 1 in the container, where SIGTERM does nothing unless handled: an old pod
63	// would keep serving the OLD app version on open keep-alive connections for the whole 30 s grace period.
64	// So: stop keeping connections alive, give the Service 3 s to stop routing here, finish in-flight requests, exit.
65	process.on("SIGTERM", () => {
66	  stopping = true;
67	  setTimeout(() => {
68	    server.close(() => pool.end().finally(() => process.exit(0)));
69	    server.closeIdleConnections();
70	  }, 3000);
71	});
72

1	-- The shop's database, as it is before every migration: 50,000 customers and 10,000,000 orders.
2	-- A quarter of the orders are guest orders with no email.
3	DROP SCHEMA IF EXISTS public CASCADE; DROP SCHEMA IF EXISTS audit CASCADE;
4	CREATE SCHEMA public;
5	CREATE TABLE customers (id integer PRIMARY KEY, name text NOT NULL);
6	CREATE TABLE orders (
7	  id          bigserial PRIMARY KEY,
8	  customer_id integer NOT NULL,
9	  amount      numeric(10,2) NOT NULL,
10	  status      text NOT NULL,
11	  email       text,
12	  created_at  timestamptz NOT NULL DEFAULT now()
13	);
14	INSERT INTO customers SELECT g, 'customer ' || g FROM generate_series(1, 50000) g;
15	INSERT INTO orders (customer_id, amount, status, email, created_at)
16	SELECT 1 + (g * 7919) % 50000,
17	       ((g * 104729) % 99999 + 100) / 100.0,
18	       (ARRAY['new','paid','shipped','delivered'])[1 + g % 4],
19	       CASE WHEN g % 4 = 0 THEN NULL ELSE 'c' || g || '@shop.test' END,
20	       now() - (g || ' seconds')::interval
21	FROM generate_series(1::bigint, 10000000::bigint) g;
22	VACUUM ANALYZE customers; VACUUM ANALYZE orders;
23	-- agent_ro: a read-only login. Reads everything, writes nothing.
24	DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'agent_ro') THEN CREATE ROLE agent_ro LOGIN; END IF; END $$;
25	GRANT pg_read_all_data TO agent_ro;
26	ALTER ROLE agent_ro SET default_transaction_read_only = on;
27	ALTER ROLE agent_ro SET statement_timeout = '10s';
