{
  "task": "rename-amount",
  "steps": [
    {
      "note": "Create the trigger function that keeps amount and total equal on every insert/update, whichever of the two the writer sets (old app writes amount, new app writes total).",
      "sql": "CREATE OR REPLACE FUNCTION orders_sync_total() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN IF TG_OP = 'INSERT' THEN IF NEW.total IS NULL THEN NEW.total := NEW.amount; ELSIF NEW.amount IS NULL THEN NEW.amount := NEW.total; END IF; ELSE IF NEW.amount IS DISTINCT FROM OLD.amount AND NEW.total IS NOT DISTINCT FROM OLD.total THEN NEW.total := NEW.amount; ELSIF NEW.total IS DISTINCT FROM OLD.total AND NEW.amount IS NOT DISTINCT FROM OLD.amount THEN NEW.amount := NEW.total; END IF; END IF; RETURN NEW; END $f$;"
    },
    {
      "note": "Add nullable column total numeric(10,2) (metadata-only, no rewrite) and the sync trigger in one transaction, so every row written from now on has total. The lock is taken with a 200 ms lock_timeout and retried, so app queries never queue behind it for long.",
      "sql": "DO $$ DECLARE tries int := 0; BEGIN LOOP BEGIN PERFORM set_config('lock_timeout', '200ms', true); ALTER TABLE orders ADD COLUMN IF NOT EXISTS total numeric(10,2); CREATE OR REPLACE TRIGGER orders_sync_total BEFORE INSERT OR UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION orders_sync_total(); EXIT; EXCEPTION WHEN lock_not_available THEN tries := tries + 1; IF tries >= 100 THEN RAISE; END IF; PERFORM pg_sleep(0.5); END; END LOOP; END $$;"
    },
    {
      "note": "Backfill total = amount for ids 1..1,000,000 in 250k-row batches, each committed on its own (row locks only; the app never updates existing orders).",
      "sql": "SET statement_timeout = 0; UPDATE orders SET total = amount WHERE id > 0 AND id <= 250000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 250000 AND id <= 500000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 500000 AND id <= 750000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 750000 AND id <= 1000000 AND total IS NULL; SELECT pg_sleep(0.5);"
    },
    { "note": "Vacuum so the dead row versions from the backfill are reused instead of bloating the table.", "sql": "VACUUM orders;" },
    {
      "note": "Backfill ids 1,000,001..2,000,000.",
      "sql": "SET statement_timeout = 0; UPDATE orders SET total = amount WHERE id > 1000000 AND id <= 1250000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 1250000 AND id <= 1500000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 1500000 AND id <= 1750000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 1750000 AND id <= 2000000 AND total IS NULL; SELECT pg_sleep(0.5);"
    },
    { "note": "Vacuum.", "sql": "VACUUM orders;" },
    {
