    },
    { "note": "Vacuum.", "sql": "VACUUM orders;" },
    {
      "note": "Backfill ids 5,000,001..6,000,000.",
      "sql": "SET statement_timeout = 0; UPDATE orders SET total = amount WHERE id > 5000000 AND id <= 5250000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 5250000 AND id <= 5500000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 5500000 AND id <= 5750000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 5750000 AND id <= 6000000 AND total IS NULL; SELECT pg_sleep(0.5);"
    },
    { "note": "Vacuum.", "sql": "VACUUM orders;" },
    {
      "note": "Backfill ids 6,000,001..7,000,000.",
      "sql": "SET statement_timeout = 0; UPDATE orders SET total = amount WHERE id > 6000000 AND id <= 6250000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 6250000 AND id <= 6500000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 6500000 AND id <= 6750000 AND total IS NULL; SELECT pg_sleep(0.5); UPDATE orders SET total = amount WHERE id > 6750000 AND id <= 7000000 AND total IS NULL; SELECT pg_sleep(0.5);"
    },
    { "note": "Vacuum.", "sql": "VACUUM orders;" },
    {
